mapper.select:
SELECT ass.cabinet_id AS cabinetId, COUNT(CASE WHEN am.severity = 'high' THEN 0 END) AS alertHigh, COUNT(CASE WHEN am.severity = 'medium' THEN 0 END) AS alertMedium, COUNT(CASE WHEN am.severity = 'low' THEN 0 END) AS alertLow FROM asset ass LEFT JOIN alert_message am ON ass.id = am.asset_id WHERE am.state = 1
/*是否只统计在库资产*/
AND ass.state = #{onlyInUse}
GROUP BY ass.cabinet_id
